  // Grammaire : les fiches détaillées existent déjà (GRAM_FULL.la) ; on ajoute la prononciation et la 1re conjugaison, et les tableaux de conjugaison.
  try{GRAM.la=(GRAM.la||[]).concat([{"t": "Prononcer le latin", "e": "On suit ici la prononciation restituée, celle de l'époque de Cicéron. C et g sont toujours durs : Cicerō se dit « Kikero ». V se dit « w » : vēnī se dit « wéni ». Ae se dit « aï », au se dit « aou ». Le s ne se dit jamais « z ». Le trait sur une voyelle (ā, ē, ī, ō, ū) indique qu'elle est longue : on la tient un peu plus longtemps. Dans les éditions des auteurs, ces traits ne sont pas écrits. À l'église et en Italie, on entend aussi la prononciation ecclésiastique (« Tchitchero », « véni »).", "x": ["Cicerō · « Kikero »", "Caesar · « Kaïsar »", "vēnī, vīdī, vīcī · « wéni, widi, wiki »", "rosa · « rossa »"], "q": [["Caesar se prononçait « ___ ».", "Kaïsar", "Sézar", "Tchézar", "Késsar"], ["Dans vēnī, le v se prononce « ___ ».", "w", "v", "b", "f"], ["Le trait sur ā indique une voyelle ___.", "longue", "accentuée", "muette", "nasale"], ["Cicerō se prononçait « ___ ».", "Kikero", "Sissero", "Tchitchero", "Gigero"]]}, {"t": "1re conjugaison : amāre", "e": "Présent : amō, amās, amat, amāmus, amātis, amant. La terminaison indique la personne : -ō (je), -s (tu), -t (il, elle), -mus (nous), -tis (vous), -nt (ils, elles). Ces terminaisons servent pour presque tous les verbes latins.", "x": ["amō, amās, amat, amāmus, amātis, amant", "Rōmam amāmus. · Nous aimons Rome.", "Nautae labōrant. · Les marins travaillent.", "Quid spectās? · Que regardes-tu ?"], "q": [["Nōs Rōmam ___.", "amāmus", "amant", "amātis", "amō"], ["Puella rosam ___.", "amat", "amant", "amō", "amās"], ["Servī ___. (travaillent)", "labōrant", "labōrat", "labōrāmus", "labōrō"], ["Quid ___ ? (tu regardes)", "spectās", "spectat", "spectō", "spectant"]]}])}catch(e){}
  try{const C={"pron": ["ego", "tū", "is / ea", "nōs", "vōs", "eī / eae"], "verbs": {"être": ["esse", "sum,es,est,sumus,estis,sunt"], "avoir": ["habēre", "habeō,habēs,habet,habēmus,habētis,habent"], "aller": ["īre", "eō,īs,it,īmus,ītis,eunt"], "faire": ["facere", "faciō,facis,facit,facimus,facitis,faciunt"], "parler": ["loquī", "loquor,loqueris,loquitur,loquimur,loquiminī,loquuntur"]}, "past": {"être": ["parfait", "fuī,fuistī,fuit,fuimus,fuistis,fuērunt"], "avoir": ["parfait", "habuī,habuistī,habuit,habuimus,habuistis,habuērunt"], "aller": ["parfait", "iī,īstī,iit,iimus,īstis,iērunt"], "faire": ["parfait", "fēcī,fēcistī,fēcit,fēcimus,fēcistis,fēcērunt"], "parler": ["parfait", "locūtus sum,locūtus es,locūtus est,locūtī sumus,locūtī estis,locūtī sunt"]}, "notes": {"parler": "Loquī est un verbe déponent : forme passive, sens actif (« je parle »)."}};CONJ.pron.la=C.pron;CONJ.verbs.la=C.verbs;CONJ.notes.la=C.notes;if(typeof CONJ_PAST!=="undefined")CONJ_PAST.la=C.past}catch(e){}
